import {renderGarageMap} from './garage-map.mjs';
/* VoltoShare tenant presentation. Server-authorised records; no local persistence. */
const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => `<img src="/static/brand/icons/icon-${name}.svg" width="24" height="24" alt="">`;
const state = {data:null, route:'dashboard', period:null, historyMonth:null, historyVehicle:'', reservationTab:'upcoming', parkingView:'map', parkingFloor:null, parkingZoom:1, selectedBay:null, selectedCharger:null, draft:null, bookingReturn:false, availabilityError:'', loading:false, received:0, busy:false};
const view = $('#app-view'), dialog = $('#app-dialog');
let toastTimer, refreshPromise, dialogSubmit, dialogTrigger;
function focusTarget(node){if(!node)return null;if(node.id)return `#${CSS.escape(node.id)}`;if(node.dataset?.action)return `[data-action="${CSS.escape(node.dataset.action)}"]${node.dataset.id?`[data-id="${CSS.escape(node.dataset.id)}"]`:""}`;return null;}
function restoreDialogFocus(){if(document.activeElement!==document.body&&document.activeElement!==dialog&&!dialog.contains(document.activeElement)){dialogTrigger=null;return;}const target=dialogTrigger?.node?.isConnected?dialogTrigger.node:document.querySelector(dialogTrigger?.selector||"[data-no-focus-target]");(target||view).focus({preventScroll:true});dialogTrigger=null;}
const zone = () => state.data?.property.timezone || 'Europe/Zurich';
const currency = () => state.data?.property.currency || 'CHF';
const number = (value, digits=3) => new Intl.NumberFormat('en-CH',{maximumFractionDigits:digits}).format(Number(value)||0);
const money = cents => new Intl.NumberFormat('en-CH',{style:'currency',currency:currency()}).format((Number(cents)||0)/100);
const tariff = value => new Intl.NumberFormat('en-CH',{style:'currency',currency:currency(),minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(value)||0);
function now(){ return new Date(state.data ? new Date(state.data.now).getTime() + Date.now()-state.received : Date.now()); }
function parts(value){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone(),year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).map(p=>[p.type,p.value]));}
function localInput(value){const p=parts(value);return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;}
function monthOf(value){return localInput(value).slice(0,7);}
function dateLabel(value, options={}){if(!value)return '—';return new Intl.DateTimeFormat('en-CH',{timeZone:zone(),day:'numeric',month:'short',year:'numeric',...options}).format(new Date(value.length===10?`${value}T12:00:00Z`:value));}
function timeLabel(value){if(!value)return '—';return new Intl.DateTimeFormat('en-GB',{timeZone:zone(),hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));}
const intervalLabel = (start,end) => `${dateLabel(start)} · ${timeLabel(start)}–${dateLabel(start)===dateLabel(end)?'':dateLabel(end)+' '}${timeLabel(end)}`;
// Advisory only: backend rejects nonexistent/ambiguous local DST times authoritatively.
function localInstant(value){if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(value||''))return NaN;const base=Date.parse(value+'Z');let t=base;for(let i=0;i<3;i++){const local=Date.parse(localInput(t)+'Z');t+=base-local;}return localInput(t)===value?t:NaN;}
function defaultDraft(){const inc=(state.data.property.booking_increment||30)*60000;const start=new Date(Math.ceil((now().getTime()+60000)/inc)*inc);return {start:localInput(start),end:localInput(new Date(start.getTime()+3600000)),vehicle_id:activeVehicles()[0]?.id||'',charger_id:state.selectedCharger||'',bay_id:state.selectedBay||'',request_id:requestID(),editing:null};}
function requestID(){return crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function activeVehicles(){return (state.data?.vehicles||[]).filter(v=>!v.archived);}
function csrf(){return decodeURIComponent(document.cookie.split('; ').find(c=>c.startsWith('csrftoken='))?.split('=').slice(1).join('=')||$('input[name=csrfmiddlewaretoken]')?.value||'');}
async function api(url,body){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json',...(body!==undefined?{'Content-Type':'application/json','X-CSRFToken':csrf()}:{})},...(body!==undefined?{method:'POST',body:JSON.stringify(body)}:{})});let result;try{result=await response.json();}catch{if(response.redirected||response.status===401){location.assign('/login/');throw new Error('Please sign in again.');}throw new Error('The server could not respond. Please try again.');}if(response.status===401){location.assign('/login/');throw new Error('Please sign in again.');}if(!response.ok||result.ok===false){const error=new Error(result.error||'This change could not be completed.');error.fields=result.fields||{};error.status=response.status;throw error;}return result;}
function toast(text){const node=$('#live-status');node.textContent=text;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,7000);}
function globalError(message){const node=$('#global-alert');node.innerHTML=message?`<span>${esc(message)}</span><button class="button small secondary" data-action="retry">Retry</button>`:'';node.hidden=!message;}
async function refresh({silent=false,render=true}={}){if(refreshPromise)return refreshPromise;refreshPromise=(async()=>{try{const data=await api('/api/state/');state.data=data;ensureBaySelection();state.received=Date.now();state.availabilityError='';if(!state.period)state.period=monthOf(data.now);if(!state.historyMonth)state.historyMonth=state.period;if(!state.draft)state.draft=defaultDraft();globalError('');updateShell();if(render)renderPage();else if(state.route==='parking')updateParkingLive();return data;}catch(e){if(e.status===403){state.data=null;if(dialog.open)dialog.close();}state.availabilityError=e.message;if(!silent||!state.data)globalError(e.message);if(state.route==='parking'&&state.data)updateParkingLive();if(!state.data)view.innerHTML=`<div class="empty-state"><h1>Your household could not load.</h1><p>Please check your connection and try again.</p><button class="button" data-action="retry">Try again</button></div>`;throw e;}finally{refreshPromise=null;}})();return refreshPromise;}
function updateShell(){const d=state.data;$('#sidebar-property').innerHTML=`<span class="eyebrow">${esc(d.property.name)}</span><strong>${esc(d.household.name)}</strong><span>Apartment ${esc(d.household.apartment)}</span>`;$('#demo-banner').hidden=!d.demo;document.querySelectorAll('[data-route]').forEach(a=>a.toggleAttribute('aria-current',a.dataset.route===state.route));document.querySelectorAll('[data-route][aria-current]').forEach(a=>a.setAttribute('aria-current','page'));const more=$('.mobile-nav [data-action=more]');more.classList.toggle('active',['history','billing'].includes(state.route));}
function monthOptions(selected){const months=new Set([monthOf(now()),selected,...state.data.sessions.map(s=>monthOf(s.end||s.start)),...state.data.reservations.map(r=>monthOf(r.start)),...state.data.invoices.map(i=>i.period.slice(0,7))]);const today=now();for(let n=0;n<12;n++){const p=parts(today),date=new Date(Date.UTC(+p.year,+p.month-1-n,15));months.add(date.toISOString().slice(0,7));}return [...months].filter(Boolean).sort().reverse().map(m=>`<option value="${m}" ${m===selected?'selected':''}>${new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-15T12:00:00Z'))}</option>`).join('');}
function periodControl(value=state.period,id='period'){return `<label class="period-control" for="${id}"><span>Period</span><select id="${id}">${monthOptions(value)}</select></label>`;}
function head(eyebrow,title,description,action=''){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="muted">${description}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty-state"><h3>${title}</h3><p>${text}</p>${action}</div>`;}
const badge=(text,type='neutral')=>`<span class="badge ${type}">${esc(text)}</span>`;
function completed(month){return state.data.sessions.filter(s=>s.status==='completed'&&monthOf(s.end)===month);}
function sum(records,key){return records.reduce((n,s)=>n+Number(s[key]||0),0);}
function outstanding(){return sum(state.data.invoices.filter(i=>i.status==='unpaid'),'total_cents');}
function reservationState(r){return r.status==='cancelled'?'Cancelled':new Date(r.end)<=now()?'Ended':new Date(r.start)<=now()?'In progress':'Upcoming';}
function isOverlap(a,b,c,d){return +new Date(a)<+new Date(d)&&+new Date(c)<+new Date(b);}
function currentStatus(c){const t=now().getTime();const reservations=state.data.occupancy.filter(o=>String(o.charger_id)===String(c.id)&&o.kind==='reservation'&&+new Date(o.start)<=t&&t<+new Date(o.end));if(c.stale||c.status==='unknown')return {label:'Status unavailable',tone:'neutral'};if(c.status==='offline')return {label:'Offline',tone:'neutral'};if(c.status==='charging')return {label:'Charging',tone:'info'};if(reservations.length)return {label:'Reserved now',tone:'warning'};return {label:'Available now',tone:'available'};}
function availableFor(c){const draft=state.draft;const start=localInstant(draft.start),end=localInstant(draft.end);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return {ok:false,label:'Choose an interval',tone:'neutral'};if(c.stale||['offline','unknown'].includes(c.status))return {ok:false,label:c.stale?'Status unavailable':c.status==='offline'?'Offline':'Status unavailable',tone:'neutral'};const old=state.data.reservations.find(r=>String(r.id)===String(draft.editing));const busy=state.data.occupancy.some(o=>String(o.charger_id)===String(c.id)&&!(old&&o.own&&o.kind==='reservation'&&+new Date(o.start)===+new Date(old.start)&&+new Date(o.end)===+new Date(old.end))&&isOverlap(start,end,o.start,o.end));if(busy)return {ok:false,label:'Occupied in this interval',tone:'warning'};const v=activeVehicles().find(v=>String(v.id)===String(draft.vehicle_id));if(v&&v.connector!==c.connector)return {ok:false,label:'Connector incompatible',tone:'neutral'};if(v&&state.data.reservations.some(r=>r.status!=='cancelled'&&String(r.id)!==String(draft.editing)&&String(r.vehicle_id)===String(v.id)&&isOverlap(start,end,r.start,r.end)))return {ok:false,label:'Vehicle already reserved',tone:'neutral'};return {ok:true,label:'Available for selected time',tone:'available'};}
function renderPage(){if(!state.data)return;const focusedId=view.contains(document.activeElement)?document.activeElement.id:null;updateShell();const renders={dashboard:dashboard,parking:parking,history:history,household:household,billing:billing};view.innerHTML=(renders[state.route]||dashboard)();document.title=`${{dashboard:'Dashboard',parking:'Parking & reservations',history:'Charging history',household:'Household & vehicles',billing:'Billing'}[state.route]} | VoltoShare`;if(state.route==='parking')updateParkingLive();if(focusedId)document.getElementById(focusedId)?.focus({preventScroll:true});}
function dashboard(){const d=state.data,ss=completed(state.period),bookings=d.reservations.filter(r=>r.status!=='cancelled'&&monthOf(r.start)===state.period),avail=d.chargers.filter(c=>currentStatus(c).label==='Available now').length;const upcoming=d.reservations.filter(r=>r.status!=='cancelled'&&new Date(r.end)>now()).sort((a,b)=>new Date(a.start)-new Date(b.start))[0];const days={};ss.forEach(s=>{const day=localInput(s.end).slice(0,10);days[day]=(days[day]||0)+Number(s.energy_kwh);});const max=Math.max(1,...Object.values(days)),dayCount=new Date(+state.period.slice(0,4),+state.period.slice(5,7),0).getDate();const bars=Array.from({length:dayCount},(_,i)=>{const day=`${state.period}-${String(i+1).padStart(2,'0')}`;return `<div class="chart-day"><div class="bar-track"><span style="height:${(days[day]||0)/max*100}%"></span></div><span>${[0,7,14,21,dayCount-1].includes(i)?i+1:''}</span></div>`;}).join('');return head(esc(d.property.name),`Hello, ${esc(d.user.name.split(' ')[0])}.`,'Your household charging, in one place.',`<a href="#parking" class="button">${icon('charger')} Reserve a charger</a>`)+`<div class="dashboard-period">${periodControl()}<span class="muted">${esc(d.household.name)} · Apartment ${esc(d.household.apartment)}</span></div><div class="stats-grid"><article class="stat primary"><span>Available now</span><strong>${avail}<small> / ${d.chargers.length}</small></strong><p>Charger status + reservations.<br>Physical bay occupancy unknown.</p></article><article class="stat"><span>Completed sessions</span><strong>${ss.length}</strong><p>${bookings.length} non-cancelled reservations<br>starting in this period</p></article><article class="stat"><span>Energy delivered</span><strong>${number(sum(ss,'energy_kwh'))}<small> kWh</small></strong><p>Completed sessions only</p></article><article class="stat"><span>Charging cost</span><strong class="money">${money(sum(ss,'cost_cents'))}</strong><p>Final session cost, not payments</p></article></div><div class="dashboard-main"><section class="panel"><div class="panel-head"><h2>Your next reservation</h2><a class="text-link" href="#parking">View all <span aria-hidden="true">↗</span></a></div>${upcoming?`<div class="next-booking">${badge(reservationState(upcoming),'available')}<h3>${esc(intervalLabel(upcoming.start,upcoming.end))}</h3><p>${esc(upcoming.charger_name)} · Bay ${esc(upcoming.bay)} · ${esc(upcoming.vehicle_name)}</p><button class="button secondary" data-action="reservation-detail" data-id="${upcoming.id}">View reservation</button></div>`:empty('Your next slot starts here.','Find a shared charger and reserve time for your household.','<a class="button" href="#parking">Choose a charger</a>')}<div class="balance-row"><div><span class="eyebrow">Outstanding invoices · all periods</span><strong>${money(outstanding())}</strong><p class="muted">Separate from this month’s charging cost.</p></div><a class="text-link" href="#billing">View billing <span aria-hidden="true">→</span></a></div></section><section class="panel"><div class="panel-head"><h2>Daily energy</h2><span class="muted">kWh · ${number(sum(ss,'energy_kwh'))} total</span></div>${ss.length?`<div class="activity-chart" aria-hidden="true"><span class="chart-scale">${number(max)} kWh</span><div class="chart-bars">${bars}</div></div><details class="chart-data"><summary>View daily values</summary><dl>${Object.entries(days).sort().map(([day,kwh])=>`<div><dt>${esc(dateLabel(day))}</dt><dd>${number(kwh)} kWh</dd></div>`).join('')}</dl></details>`:empty('No completed sessions this month.','Energy appears here only when a completed charging session has been recorded.')}<p class="note">Sessions are assigned to the month of their end time in ${esc(zone())}.</p></section></div><section class="panel"><div class="panel-head"><h2>Recent charging</h2><a href="#history" class="text-link">Charging history <span aria-hidden="true">↗</span></a></div>${sessionTable([...ss].sort((a,b)=>new Date(b.end)-new Date(a.end)).slice(0,5))}</section>`;}

function bayCharger(b){return state.data.chargers.find(c=>String(c.id)===String(b?.charger_id));}
function selectedBay(){return state.data.bays.find(b=>String(b.id)===String(state.selectedBay));}
function floorName(f){return String(f||'UG1').replace(/^UG(\d+)$/,'Level −$1');}
function ensureBaySelection(){const bays=state.data.bays;let b=bays.find(b=>String(b.id)===String(state.selectedBay));if(!b)b=bays.find(b=>String(b.charger_id)===String(state.selectedCharger))||bays[0];if(b){state.selectedBay=b.id;state.selectedCharger=b.charger_id;state.parkingFloor=state.parkingFloor||b.floor||'UG1';}if(!bays.some(x=>(x.floor||'UG1')===state.parkingFloor))state.parkingFloor=b?.floor||'UG1';}
function selectBay(id){const b=state.data.bays.find(b=>String(b.id)===String(id));if(!b)return;state.selectedBay=b.id;state.selectedCharger=b.charger_id;state.parkingFloor=b.floor||'UG1';state.draft.bay_id=b.id;state.draft.charger_id=b.charger_id||'';state.draft.request_id=requestID();updateParkingLive();}
function availableForBay(b){if(!b||b.bookable===false)return {ok:false,label:'Not reservable',tone:'neutral'};const start=localInstant(state.draft.start),end=localInstant(state.draft.end);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||start<=now())return {ok:false,label:'Choose a future interval',tone:'neutral'};const c=bayCharger(b);if(c)return availableFor(c);const old=state.data.reservations.find(r=>String(r.id)===String(state.draft.editing));if(state.data.occupancy.some(o=>String(o.bay_id)===String(b.id)&&!(old&&o.own&&o.kind==='reservation'&&String(old.bay_id)===String(o.bay_id)&&+new Date(old.start)===+new Date(o.start)&&+new Date(old.end)===+new Date(o.end))&&isOverlap(start,end,o.start,o.end)))return {ok:false,label:'Reserved for this time',tone:'warning'};if(state.data.reservations.some(r=>r.status!=='cancelled'&&String(r.id)!==String(state.draft.editing)&&String(r.vehicle_id)===String(state.draft.vehicle_id)&&isOverlap(start,end,r.start,r.end)))return {ok:false,label:'Vehicle already reserved',tone:'neutral'};return {ok:true,label:'Available for selected time',tone:'available'};}

function parking(){const draft=state.draft;return head('Your garage, at a glance','Parking & reservations',`Choose your floor and tap a parking space. Charging and ordinary spaces are shown together.`)+`<section class="panel booking-panel"><div class="panel-head"><div><h2>${draft.editing?'Change your reservation':'When would you like to park?'}</h2><p class="muted">${state.data.property.booking_increment}-minute increments · ${state.data.property.min_minutes}–${state.data.property.max_minutes} minutes · times in ${esc(zone())}</p></div>${draft.editing?'<button class="text-link" data-action="discard-edit">Cancel editing</button>':''}</div><div class="booking-inputs"><label class="field">Starts<input id="booking-start" type="datetime-local" step="${state.data.property.booking_increment*60}" value="${esc(draft.start)}" required></label><label class="field">Ends<input id="booking-end" type="datetime-local" step="${state.data.property.booking_increment*60}" value="${esc(draft.end)}" required></label><label class="field">Vehicle<select id="booking-vehicle"><option value="">Choose a vehicle</option>${activeVehicles().map(v=>`<option value="${v.id}" ${String(v.id)===String(draft.vehicle_id)?'selected':''}>${esc(v.name)} · ${esc(v.plate)}</option>`).join('')}</select></label></div><div class="booking-help"><p class="note">1. Choose a time &nbsp; 2. Select a space &nbsp; 3. Confirm your reservation</p><button class="text-link" data-action="booking-add-vehicle">${activeVehicles().length?'Add another vehicle':'Add a vehicle to continue'} ↗</button></div><p id="booking-error" class="error-text" role="alert" hidden></p></section><div class="parking-workspace garage-workspace"><section class="panel parking-panel"><div class="panel-head"><div><span class="eyebrow">Floor plan</span><h2>Find your space</h2></div><div class="segmented" aria-label="Parking view"><button data-action="parking-view" data-view="map" aria-pressed="${state.parkingView==='map'}">Garage map</button><button data-action="parking-view" data-view="list" aria-pressed="${state.parkingView==='list'}">Space list</button></div></div><label class="field garage-search-label">Find a space on any floor<input id="parking-search" type="search" placeholder="e.g. P03" list="parking-space-options"><datalist id="parking-space-options">${state.data.bays.map(b=>`<option value="${esc(b.label)}">${esc(floorName(b.floor))}</option>`).join('')}</datalist></label><div id="parking-live"></div></section><section id="charger-details" class="panel charger-details" aria-label="Selected parking space"></section></div><section class="panel"><div class="panel-head"><h2>Household reservations</h2><span class="note">Changes and cancellation only before the start time.</span></div><div class="segmented reservation-tabs" aria-label="Reservation filter">${['upcoming','past','cancelled'].map(tab=>`<button data-action="reservation-tab" data-tab="${tab}" aria-pressed="${state.reservationTab===tab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div id="reservation-list">${reservationList()}</div></section>`;}
function parkingVisual(){const floors=[...new Set(state.data.bays.map(b=>b.floor||'UG1'))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));const bays=state.data.bays.filter(b=>(b.floor||'UG1')===state.parkingFloor),available=bays.filter(b=>availableForBay(b).ok).length,charging=bays.filter(b=>b.charger_id).length;return `<div class="garage-floors" role="group" aria-label="Garage floors">${floors.map(f=>{const list=state.data.bays.filter(b=>(b.floor||'UG1')===f);return `<button class="garage-floor-tab" data-action="parking-floor" data-id="${esc(f)}" aria-pressed="${f===state.parkingFloor}"><strong>${esc(floorName(f))}</strong><span>${list.length} spaces · ${list.filter(b=>b.charger_id).length} charging</span></button>`;}).join('')}</div><div class="garage-map-heading"><p><strong>${available}</strong> reservable for your vehicle · ${bays.length} spaces · ${charging} with charging</p>${state.parkingView==='map'?`<div class="garage-zoom" role="group" aria-label="Map zoom"><button class="icon-button" data-action="map-zoom-out" aria-label="Zoom out">−</button><button class="text-link" data-action="map-zoom-reset">${Math.round(state.parkingZoom*100)}%</button><button class="icon-button" data-action="map-zoom-in" aria-label="Zoom in">+</button></div>`:''}</div>${state.parkingView==='map'?renderGarageMap({bays,chargers:state.data.chargers,selectedBay:state.selectedBay,availability:availableForBay,floor:state.parkingFloor,zoom:state.parkingZoom}):`<div class="charger-list garage-space-list">${bays.map(b=>{const c=bayCharger(b),a=availableForBay(b);return `<button class="charger-list-row ${String(b.id)===String(state.selectedBay)?'selected':''}" data-action="select-bay" data-id="${b.id}" aria-pressed="${String(b.id)===String(state.selectedBay)}"><span>${icon(c?'charger':'car')}<strong>${esc(b.label)} · ${esc(floorName(b.floor))}</strong><small>${c?esc(c.name)+' · '+esc(c.connector)+' · '+number(c.max_power_kw)+' kW':'Parking only · no charger'}</small></span>${badge(a.label,a.tone)}</button>`;}).join('')}</div>`}<div class="garage-legend"><span><i class="available"></i>Available</span><span><i class="warning"></i>Reserved</span><span><i class="neutral"></i>Unavailable</span><span><b>EV</b> With charger</span><span><b>P</b> Parking only</span></div><div class="availability-refresh ${state.availabilityError?'refresh-failed':''}" role="status">${state.availabilityError?`<strong>Availability could not refresh.</strong> ${esc(state.availabilityError)} <button class="text-link" data-action="refresh-parking">Retry</button>`:`Updated ${esc(timeLabel(state.data.now))} · ${state.data.demo?'demo reservations & simulated charger status':'reservation availability'}`}</div><p class="note">Availability is for your selected time, not a live parking sensor. Physical occupancy is unknown.</p>`;}
function chargerDetail(){const b=selectedBay();if(!b)return empty('Choose a parking space.','Tap a numbered space on the map or choose it from the list.');const c=bayCharger(b),future=availableForBay(b),occupancies=state.data.occupancy.filter(o=>String(o.bay_id)===String(b.id)&&new Date(o.end)>now()).sort((a,b)=>new Date(a.start)-new Date(b.start)).slice(0,4);return `<div class="charger-detail-head garage-selection"><button class="text-link garage-back-map" data-action="show-map">← Back to garage map</button><span class="eyebrow">${esc(floorName(b.floor))} · selected space</span><div class="garage-selected-number">${esc(b.label)}${icon(c?'charger':'car')}</div><h2>${c?'Charging & parking':'Parking only'}</h2><p class="muted">${c?esc(c.name)+' · '+esc(c.connector):'Ordinary space · no charging equipment'}</p></div><div class="status-pair"><span>Your selected time</span>${badge(future.label,future.tone)}</div><p class="garage-selection-time">${Number.isFinite(localInstant(state.draft.start))&&Number.isFinite(localInstant(state.draft.end))?esc(intervalLabel(localInstant(state.draft.start),localInstant(state.draft.end))):'Choose your start and end time above.'}</p>${c?`<dl class="detail-grid"><div><dt>Maximum power</dt><dd>${number(c.max_power_kw)} kW</dd></div><div><dt>${state.data.demo?'Sample energy tariff':'Energy tariff'}</dt><dd>${tariff(c.tariff_chf)} / kWh</dd></div><div><dt>Charger right now</dt><dd>${esc(currentStatus(c).label)}</dd></div><div><dt>Floor</dt><dd>${esc(floorName(b.floor))}</dd></div></dl>`:'<p class="notice">This reserves the parking space only. No charging session, energy bill or payment is created.</p>'}<button class="button full-width" data-action="review-booking" ${!future.ok||!state.draft.vehicle_id||state.availabilityError?'disabled':''}>${state.draft.editing?'Review change':'Reserve '+esc(b.label)} →</button>${!state.draft.vehicle_id?'<p class="note">Choose a household vehicle above to continue.</p>':''}<p class="note garage-selection-note">${c?'Reserves access, not charging power. Actual usage is billed from charging sessions.':'Demo parking access; no parking payment is processed.'} Availability is rechecked when you confirm.</p><div class="occupied-intervals"><h3>Upcoming reservations</h3>${occupancies.length?occupancies.map(o=>`<p>${esc(intervalLabel(o.start,o.end))}<br><small>${o.kind==='session'?'Charging · release time unconfirmed':o.own?'Your household':'Another household'}</small></p>`).join(''):'<p class="muted">No recorded occupied intervals ahead.</p>'}</div>`;}
function updateParkingLive(){if(state.route!=='parking')return;const focused=document.activeElement;const action=focused?.dataset?.action,id=focused?.dataset?.id;const scroller=view.querySelector('.garage-scroll'),scroll=scroller?{left:scroller.scrollLeft,top:scroller.scrollTop}:null;const live=$('#parking-live'),details=$('#charger-details');if(live)live.innerHTML=parkingVisual();if(details)details.innerHTML=chargerDetail();const nextScroller=view.querySelector('.garage-scroll');if(scroll&&nextScroller){nextScroller.scrollLeft=scroll.left;nextScroller.scrollTop=scroll.top;}const list=$('#reservation-list');if(list)list.innerHTML=reservationList();if(action&&!document.contains(focused)){const selector=`[data-action="${CSS.escape(action)}"]${id?`[data-id="${CSS.escape(id)}"]`:''}`;view.querySelector(selector)?.focus({preventScroll:true});}}
function reservationList(){const rows=state.data.reservations.filter(r=>state.reservationTab==='cancelled'?r.status==='cancelled':r.status!=='cancelled'&&(state.reservationTab==='past'?new Date(r.end)<=now():new Date(r.end)>now())).sort((a,b)=>state.reservationTab==='upcoming'?new Date(a.start)-new Date(b.start):new Date(b.start)-new Date(a.start));if(!rows.length)return empty('No reservations in this view.','Your household bookings will appear here. Ended reservations do not necessarily mean charging occurred.');return `<div class="reservation-cards">${rows.map(r=>`<article class="reservation-card"><div><div class="inline-meta">${badge(reservationState(r),reservationState(r)==='Upcoming'?'available':'neutral')}<span>${esc(r.charger_name)} · ${esc(r.bay)} · ${esc(floorName(r.floor))}</span></div><h3>${esc(intervalLabel(r.start,r.end))}</h3><p>${esc(r.vehicle_name)} · Booked by ${esc(r.creator_name)}</p></div><button class="button secondary small" data-action="reservation-detail" data-id="${r.id}">Details</button></article>`).join('')}</div>`;}
function sessionTable(rows){if(!rows.length)return empty('No charging sessions match.','Try a different month or vehicle. Reservations alone do not create charging records.');return `<div class="table-scroll" tabindex="0" role="region" aria-label="Charging sessions"><table><thead><tr><th>Session ended</th><th>Vehicle / driver</th><th>Charger</th><th>Energy</th><th>Cost</th><th>State</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(dateLabel(s.end||s.start))}<small>${esc(timeLabel(s.start))}–${s.end?esc(timeLabel(s.end)):'ongoing'}</small></td><td>${esc(s.vehicle_name)}<small>${esc(s.driver_name||'Driver not recorded')}</small></td><td>${esc(s.bay)}<small>${esc(state.data.chargers.find(c=>String(c.id)===String(s.charger_id))?.name||'Charger')}</small></td><td>${number(s.energy_kwh)} kWh</td><td>${s.status==='completed'?money(s.cost_cents):'Provisional'}</td><td>${badge(s.status==='completed'?'Completed':'Active',s.status==='completed'?'available':'info')}<small>${s.invoice_id?'Invoiced':s.status==='completed'?'Unbilled':'Provisional readings'}</small></td><td><button class="text-link" data-action="session-detail" data-id="${s.id}" aria-label="View session on ${esc(dateLabel(s.end||s.start))}">View</button></td></tr>`).join('')}</tbody></table></div>`;}
function history(){const rows=state.data.sessions.filter(s=>monthOf(s.end||s.start)===state.historyMonth&&(!state.historyVehicle||String(s.vehicle_id)===state.historyVehicle)).sort((a,b)=>new Date(b.end||b.start)-new Date(a.end||a.start));const finalized=rows.filter(s=>s.status==='completed');const vehicles=new Map(state.data.sessions.map(s=>[String(s.vehicle_id),s.vehicle_name]));const query=new URLSearchParams({month:state.historyMonth,...(state.historyVehicle?{vehicle:state.historyVehicle}:{})});return head('Your household activity','Charging history','Energy delivered, actual session costs and billing links.',`<a class="button secondary" href="/api/history.csv?${esc(query)}">Download CSV <span aria-hidden="true">↓</span></a>`)+`<section class="panel"><div class="filters">${periodControl(state.historyMonth,'history-month')}<label class="field" for="history-vehicle">Vehicle<select id="history-vehicle"><option value="">All household vehicles</option>${[...vehicles].map(([id,name])=>`<option value="${esc(id)}" ${state.historyVehicle===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label><button class="text-link" data-action="history-reset">Reset filters</button></div><div class="summary-line"><div><span>Completed sessions</span><strong>${finalized.length}</strong></div><div><span>Energy delivered</span><strong>${number(sum(finalized,'energy_kwh'))} kWh</strong></div><div><span>Final charging cost</span><strong>${money(sum(finalized,'cost_cents'))}</strong></div></div>${sessionTable(rows)}<p class="note">Reporting uses each completed session’s end time in ${esc(zone())}. Active-session values are provisional and excluded from totals. Charging cost is not the same as a payment.</p></section>`;}
function household(){const d=state.data,owner=d.role==='owner';return head(`Apartment ${esc(d.household.apartment)}`,esc(d.household.name),'Shared vehicles, activity and billing for your household.',owner?'<button class="button secondary" data-action="household-edit">Edit household</button>':'')+`${state.bookingReturn?'<div class="notice return-notice"><div><strong>Your charging slot is saved.</strong><p>Add a vehicle, then return to your reservation without choosing the time again.</p></div><button class="button" data-action="return-booking">Return to booking →</button></div>':''}<section class="panel"><div class="panel-head"><div><h2>Your vehicles</h2><p class="muted">Household members can manage vehicles. Archived vehicles stay in historical records.</p></div><button class="button" data-action="vehicle-add">${icon('car')} Add vehicle</button></div>${activeVehicles().length?`<div class="vehicle-grid">${activeVehicles().map(v=>`<article class="vehicle-card"><div class="vehicle-heading">${icon('car')}<span class="plate">${esc(v.plate)}</span></div><h3>${esc(v.name)}</h3><p class="muted">${esc(v.make_model||'Make / model not specified')}</p><dl class="compact-details"><div><dt>Primary driver</dt><dd>${esc(v.driver_name||'Not assigned')}</dd></div><div><dt>Connector</dt><dd>${esc(v.connector)}</dd></div><div><dt>Battery</dt><dd>${v.battery_kwh?number(v.battery_kwh)+' kWh':'Not specified'}</dd></div></dl><div class="card-actions"><button class="text-link" data-action="vehicle-edit" data-id="${v.id}">Edit vehicle</button><button class="text-link danger-text" data-action="vehicle-archive" data-id="${v.id}">Archive</button></div></article>`).join('')}</div>`:empty('Add your first vehicle.','A registered household vehicle is required to reserve a charger.','<button class="button" data-action="vehicle-add">Add a vehicle</button>')}</section><section class="panel"><div class="panel-head"><div><h2>Household members</h2><p class="muted">Everyone shares household reservations, vehicles, charging history and invoices.</p></div>${owner?'<button class="button secondary" data-action="invite">Invite a member</button>':''}</div><div class="member-list">${d.members.map(m=>`<article class="member-row"><span class="avatar" aria-hidden="true">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}${m.user_id===d.user.id?' · you':''}</strong><span>${esc(m.email)}</span></div>${badge(m.role==='owner'?'Owner':'Member')}${owner&&!(m.role==='owner'&&d.members.filter(x=>x.role==='owner').length===1)?`<button class="text-link danger-text" data-action="member-remove" data-id="${m.id}">Remove<span class="sr-only"> ${esc(m.name)}</span></button>`:''}</article>`).join('')}</div><p class="note">Only owners manage membership. Removing access preserves historical charging and bookings. The last owner cannot be removed.</p></section>${owner?`<section class="panel"><div class="panel-head"><h2>Invitations</h2><span class="note">Copyable links · no email delivery</span></div>${d.invitations?.length?`<div class="member-list">${d.invitations.map(i=>`<article class="member-row"><div><strong>${esc(i.email)}</strong><span>Expires ${esc(dateLabel(i.expires_at))} · ${esc(timeLabel(i.expires_at))}</span></div>${badge(i.revoked?'Revoked':i.used?'Accepted':new Date(i.expires_at)<now()?'Expired':'Pending',!i.revoked&&!i.used&&new Date(i.expires_at)>now()?'warning':'neutral')}${!i.revoked&&!i.used?`<button class="text-link danger-text" data-action="invite-revoke" data-id="${i.id}">Revoke</button>`:''}</article>`).join('')}</div>`:empty('No invitations yet.','An expiring, email-bound invitation link lets someone join this household. No email is sent automatically.')}</section>`:''}`;}
function billing(){const d=state.data,ss=completed(state.period),unbilled=ss.filter(s=>!s.invoice_id),overdue=sum(d.invoices.filter(i=>i.status==='unpaid'&&i.overdue),'total_cents');return head('Your household account','Billing','Understand what was charged, invoiced and paid.',periodControl())+`<div class="stats-grid"><article class="stat"><span>Charging cost · selected month</span><strong class="money">${money(sum(ss,'cost_cents'))}</strong><p>Final completed session costs</p></article><article class="stat"><span>Unbilled · selected month</span><strong class="money">${money(sum(unbilled,'cost_cents'))}</strong><p>Completed usage, not yet invoiced</p></article><article class="stat primary"><span>Outstanding · all periods</span><strong class="money">${money(outstanding())}</strong><p>Unpaid issued invoices</p></article><article class="stat"><span>Overdue · all periods</span><strong class="money ${overdue?'danger-text':''}">${money(overdue)}</strong><p>Unpaid and past the due date</p></article></div><section class="panel"><div class="panel-head"><h2>Issued invoices</h2>${badge(d.demo?'Sample billing data':'Household invoices',d.demo?'warning':'neutral')}</div>${d.invoices.length?`<div class="table-scroll" tabindex="0" role="region" aria-label="Household invoices"><table><thead><tr><th>Invoice</th><th>Period</th><th>Total</th><th>Due</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${[...d.invoices].sort((a,b)=>b.period.localeCompare(a.period)).map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(i.period)}</td><td>${money(i.total_cents)}</td><td>${esc(dateLabel(i.due_date))}</td><td>${badge(i.status==='paid'?'Paid':i.overdue?'Overdue':'Unpaid',i.status==='paid'?'available':i.overdue?'danger':'warning')}</td><td><button class="text-link" data-action="invoice-detail" data-id="${i.id}">View invoice</button></td></tr>`).join('')}</tbody></table></div>`:empty('No invoices have been issued.','Completed sessions remain unbilled until an invoice is issued.')}<p class="note">Invoice totals are not added again to charging cost. Payment status comes from the billing records; this app does not process payments. ${d.demo?'All displayed tariffs, invoices and payment states are fictional demo data.':''}</p></section>`;}
function openDialog(title,body,{wide=false,submit=null}={}){if(!dialog.open)dialogTrigger={node:document.activeElement,selector:focusTarget(document.activeElement)};dialogSubmit=submit;$('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">×</button></div>${body}`;dialog.classList.toggle('wide',wide);if(!dialog.open)dialog.showModal();}
function closeDialog(){if(state.busy)return;dialog.close();dialogSubmit=null;}
function errorMarkup(){return '<p id="dialog-error" class="error-text" role="alert" hidden></p>';}
function dialogError(error){const node=$('#dialog-error');if(node){node.hidden=false;node.textContent=error.message;node.tabIndex=-1;node.focus();}for(const [key,message]of Object.entries(error.fields||{})){const input=$(`[name="${CSS.escape(key)}"]`,dialog);if(input){input.setAttribute('aria-invalid','true');const msg=document.createElement('span');msg.className='error-text field-server-error';msg.textContent=Array.isArray(message)?message.join(' '):String(message);input.closest('label')?.append(msg);}}}
async function mutate(url,body,{success,onSuccess,keepOpen=false}={}){if(state.busy)return;state.busy=true;const buttons=[...dialog.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const error=$('#dialog-error');if(error)error.hidden=true;dialog.querySelectorAll('.field-server-error').forEach(n=>n.remove());try{const result=await api(url,body);await refresh({render:false});state.busy=false;if(onSuccess)await onSuccess(result);if(!keepOpen)dialog.close();renderPage();if(success)toast(success);return result;}catch(e){dialogError(e);await refresh({silent:true,render:false}).catch(()=>{});}finally{state.busy=false;buttons.forEach(b=>b.disabled=false);}}
function bookingReview(){const draft=state.draft,b=selectedBay(),c=bayCharger(b),v=activeVehicles().find(v=>String(v.id)===String(draft.vehicle_id));const start=localInstant(draft.start),end=localInstant(draft.end),minutes=(end-start)/60000,p=state.data.property;let error='';if(!Number.isFinite(start)||!Number.isFinite(end))error='Choose valid start and end times.';else if(start<=now())error='Your reservation must start in the future.';else if(minutes<p.min_minutes||minutes>p.max_minutes)error=`Choose a duration between ${p.min_minutes} and ${p.max_minutes} minutes.`;else if(start>now().getTime()+p.horizon_days*86400000)error=`Choose a start within the next ${p.horizon_days} days.`;else if(+draft.start.slice(-2)%p.booking_increment||+draft.end.slice(-2)%p.booking_increment)error=`Start and end times must use ${p.booking_increment}-minute increments.`;else if(!v)error='Choose a registered household vehicle.';else if(!b||!availableForBay(b).ok)error='This parking space is not available for the selected interval. Please choose an alternative.';const err=$('#booking-error');if(error){err.textContent=error;err.hidden=false;err.tabIndex=-1;err.focus();return;}err.hidden=true;draft.charger_id=c?.id||'';draft.bay_id=b.id;openDialog(draft.editing?'Review reservation change':'Review your reservation',`<div class="review-highlight">${icon(c?'charger':'car')}<div><h3>${esc(b.label)} · ${esc(floorName(b.floor))} · ${c?'With charging':'Parking only'}</h3><p>${esc(intervalLabel(start,end))}</p></div></div><dl class="detail-grid"><div><dt>Vehicle</dt><dd>${esc(v.name)} · ${esc(v.plate)}</dd></div><div><dt>Duration</dt><dd>${number(minutes,0)} minutes</dd></div><div><dt>${c?(state.data.demo?'Illustrative flat tariff':'Tariff'):'Reservation type'}</dt><dd>${c?tariff(c.tariff_chf)+' / kWh':'Parking only · no charger'}</dd></div><div><dt>Timezone</dt><dd>${esc(zone())}</dd></div></dl><p class="notice">This reserves access only. No energy is recorded and no payment is taken. ${c?'Actual usage is billed from completed charging sessions, not reserved hours.':'No charging session or invoice is created for this parking-only reservation.'}</p><p class="note">Availability is checked again when you confirm. You can change or cancel before the start time.</p>${errorMarkup()}<form id="dialog-form"><div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">Back</button><button class="button" type="submit">${draft.editing?'Confirm change':'Confirm reservation'}</button></div></form>`,{submit:()=>mutate(draft.editing?`/api/reservations/${draft.editing}/change/`:'/api/reservations/',{bay_id:b.id,...(c?{charger_id:c.id}:{}),vehicle_id:v.id,start:draft.start,end:draft.end,request_id:draft.request_id},{success:draft.editing?'Reservation updated. No charging cost was created.':'Reservation confirmed. No charging cost was created.',onSuccess:()=>{state.draft={...draft,editing:null,request_id:requestID()};state.bookingReturn=false;}})});}
function reservationDialog(id){const r=state.data.reservations.find(r=>String(r.id)===String(id));if(!r)return;const editable=r.status!=='cancelled'&&new Date(r.start)>now();openDialog('Reservation details',`<p>${badge(reservationState(r),editable?'available':'neutral')}</p><div class="review-highlight"><div><h3>${esc(r.charger_name)} · ${esc(r.bay)} · ${esc(floorName(r.floor))}</h3><p>${esc(intervalLabel(r.start,r.end))}</p></div></div><dl class="detail-grid"><div><dt>Vehicle</dt><dd>${esc(r.vehicle_name)}</dd></div><div><dt>Booked by</dt><dd>${esc(r.creator_name)}</dd></div></dl><p class="note">An ended reservation is not proof of charging. Changes and cancellations are allowed only before the start time.</p>${editable?`<div class="dialog-actions"><button class="button secondary" data-action="reservation-edit" data-id="${r.id}">Change reservation</button><button class="button danger" data-action="reservation-cancel" data-id="${r.id}">Cancel reservation</button></div>`:''}`);}
function confirmDialog(title,text,url,body={},success='Change saved.'){openDialog(title,`<p>${text}</p>${errorMarkup()}<form id="dialog-form"><div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">Go back</button><button type="submit" class="button danger">Confirm</button></div></form>`,{submit:()=>mutate(url,body,{success})});}
function vehicleDialog(id){const v=state.data.vehicles.find(v=>String(v.id)===String(id))||{},connectors=[...new Set([...state.data.chargers.map(c=>c.connector),v.connector].filter(Boolean))];openDialog(v.id?'Edit vehicle':'Add a vehicle',`<form id="dialog-form"><div class="form-grid"><label class="field">Vehicle name<input name="name" required maxlength="100" value="${esc(v.name)}" autocomplete="off"></label><label class="field">Registration plate<input name="plate" required maxlength="30" value="${esc(v.plate)}" autocomplete="off"></label><label class="field full">Make and model <span class="muted">(optional)</span><input name="make_model" maxlength="120" value="${esc(v.make_model)}"></label><label class="field">Primary driver<select name="driver_id"><option value="">Not assigned</option>${state.data.members.map(m=>`<option value="${m.user_id}" ${String(m.user_id)===String(v.driver_id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label class="field">Connector<select name="connector" required>${connectors.map(c=>`<option ${v.connector===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field full">Battery capacity, kWh <span class="muted">(optional)</span><input name="battery_kwh" type="number" min="0.1" step="0.1" value="${esc(v.battery_kwh)}"><small>Use the vehicle’s known capacity; do not guess.</small></label></div>${errorMarkup()}<div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">Cancel</button><button class="button" type="submit">${v.id?'Save changes':'Add vehicle'}</button></div></form>`,{submit:form=>{const values=Object.fromEntries(new FormData(form));values.driver_id=values.driver_id?Number(values.driver_id):null;values.battery_kwh=values.battery_kwh||null;return mutate(v.id?`/api/vehicles/${v.id}/change/`:'/api/vehicles/',values,{success:v.id?'Vehicle updated.':'Vehicle added to your household.',onSuccess:result=>{if(state.bookingReturn){state.draft.vehicle_id=result.vehicle_id||v.id;state.draft.request_id=requestID();}}});}});}
function inviteDialog(){openDialog('Invite a household member',`<p>Create an expiring invitation for this email address. The recipient must sign in or register through the link to join your household.</p><form id="dialog-form"><label class="field">Recipient email<input type="email" name="email" required maxlength="254" autocomplete="off"></label><p class="note">No email is sent. You will receive a link to copy and share yourself.</p>${errorMarkup()}<div class="dialog-actions"><button class="button secondary" type="button" data-action="close-dialog">Cancel</button><button type="submit" class="button">Create invitation link</button></div></form>`,{submit:form=>mutate('/api/invitations/',Object.fromEntries(new FormData(form)),{keepOpen:true,onSuccess:result=>openDialog('Your invitation link is ready',`<p class="notice">No email was sent. Share this link directly with the intended recipient. It can be used once and expires ${esc(dateLabel(result.expires_at))} at ${esc(timeLabel(result.expires_at))}.</p><label class="field">Invitation link<input id="invitation-link" type="url" readonly value="${esc(result.url)}"></label><p class="note">For privacy, this full link is shown only now. Create a new invitation if you lose it.</p><p id="copy-status" role="status"></p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">Done</button><button class="button" data-action="copy-invitation">Copy link</button></div>`)})});}
function sessionDialog(id){const s=state.data.sessions.find(s=>String(s.id)===String(id));if(!s)return;openDialog('Charging session',`<p>${badge(s.status==='completed'?'Completed':'Active · provisional',s.status==='completed'?'available':'info')}</p><h3 class="spaced">${esc(dateLabel(s.end||s.start))}</h3><dl class="detail-grid"><div><dt>Start</dt><dd>${esc(dateLabel(s.start))} · ${esc(timeLabel(s.start))}</dd></div><div><dt>End</dt><dd>${s.end?esc(dateLabel(s.end))+' · '+esc(timeLabel(s.end)):'Ongoing'}</dd></div><div><dt>Duration</dt><dd>${s.end?number((new Date(s.end)-new Date(s.start))/60000,0)+' minutes':'In progress'}</dd></div><div><dt>Charger / bay</dt><dd>${esc(state.data.chargers.find(c=>String(c.id)===String(s.charger_id))?.name||'Charger')} / ${esc(s.bay)}</dd></div><div><dt>Vehicle / driver</dt><dd>${esc(s.vehicle_name)} / ${esc(s.driver_name||'Not recorded')}</dd></div><div><dt>Energy delivered</dt><dd>${number(s.energy_kwh)} kWh</dd></div><div><dt>Recorded tariff</dt><dd>${tariff(s.tariff_chf)} / kWh</dd></div><div><dt>${s.status==='completed'?'Final cost':'Provisional cost'}</dt><dd>${money(s.cost_cents)}</dd></div></dl>${s.invoice_id?`<button class="button secondary" data-action="invoice-detail" data-id="${s.invoice_id}">View associated invoice</button>`:'<p class="notice">This session has not been included in an issued invoice.</p>'}<p class="note">${state.data.demo?'Sample session and tariff. ':''}Historical session costs keep their recorded tariff. No payment is processed here.</p>`);}
function invoiceDialog(id){const i=state.data.invoices.find(i=>String(i.id)===String(id));if(!i)return;openDialog(`Invoice ${i.number}`,`<div class="invoice-intro"><div><strong>${esc(i.household_name||state.data.household.name)}</strong><p>${esc(i.property_name||state.data.property.name)} · Apartment ${esc(i.apartment||state.data.household.apartment)}</p></div>${badge(i.status==='paid'?'Paid':i.overdue?'Overdue':'Unpaid',i.status==='paid'?'available':i.overdue?'danger':'warning')}</div><dl class="detail-grid"><div><dt>Billing period</dt><dd>${esc(i.period)}</dd></div><div><dt>Issued</dt><dd>${esc(dateLabel(i.issued_at))}</dd></div><div><dt>Due</dt><dd>${esc(dateLabel(i.due_date))}</dd></div><div><dt>Payment recorded</dt><dd>${i.paid_at?esc(dateLabel(i.paid_at)):'Not paid'}</dd></div></dl><div class="table-scroll" tabindex="0" role="region" aria-label="Invoice line items"><table><thead><tr><th>Date / vehicle</th><th>Charger</th><th>Energy</th><th>Tariff</th><th>Charge</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${esc(dateLabel(l.date))}<small>${esc(l.vehicle)}</small></td><td>${esc(l.charger)}<small>${esc(l.bay)}</small></td><td>${number(l.energy_kwh)} kWh</td><td>${tariff(l.tariff_chf)} / kWh</td><td>${money(l.cost_cents)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-total"><span>Total · ${esc(i.currency||currency())}</span><strong>${money(i.total_cents)}</strong></div><p class="note">${state.data.demo?'Fictional sample invoice. ':''}Issued line items preserve the recorded vehicle, tariff and cost. Production tax treatment remains a separate configuration decision.</p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">Close</button><a class="button" href="/invoices/${i.id}/print/" target="_blank" rel="noopener">Print / save as PDF ↗</a></div>`,{wide:true});}
function changeRoute(route){if(!['dashboard','parking','history','household','billing'].includes(route))route='dashboard';state.route=route;renderPage();window.scrollTo({top:0});}
window.addEventListener('hashchange',()=>{changeRoute(location.hash.slice(1));if(state.data)refresh({silent:true,render:state.route!=='parking'}).catch(()=>{});});
document.addEventListener('input',e=>{if(['booking-start','booking-end','booking-vehicle'].includes(e.target.id)){const key={'booking-start':'start','booking-end':'end','booking-vehicle':'vehicle_id'}[e.target.id];state.draft[key]=e.target.value;state.draft.request_id=requestID();$('#booking-error').hidden=true;updateParkingLive();}});
document.addEventListener('change',e=>{if(e.target.id==='parking-search'){const b=state.data.bays.find(b=>b.label.toLowerCase()===e.target.value.trim().toLowerCase());if(b){selectBay(b.id);requestAnimationFrame(()=>view.querySelector('.garage-scroll [data-action="select-bay"][data-id="'+b.id+'"]')?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'}));}else if(e.target.value)toast('No space with that number. Choose a space from the suggestions.');}if(e.target.id==='period'){state.period=e.target.value;renderPage();}if(e.target.id==='history-month'){state.historyMonth=e.target.value;renderPage();}if(e.target.id==='history-vehicle'){state.historyVehicle=e.target.value;renderPage();}});
dialog.addEventListener('cancel',e=>{if(state.busy)e.preventDefault();});
dialog.addEventListener('close',()=>{dialogSubmit=null;requestAnimationFrame(restoreDialogFocus);});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();view.focus();view.scrollIntoView({block:'start'});});
dialog.addEventListener('submit',e=>{if(e.target.id==='dialog-form'){e.preventDefault();if(!state.busy&&dialogSubmit)dialogSubmit(e.target);}});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;if(state.busy&&dialog.contains(target))return;try{
if(a==='close-dialog')closeDialog();
else if(a==='retry')await refresh();
else if(a==='refresh-parking')await refresh({render:false});
else if(a==='select-charger'){const b=state.data.bays.find(b=>String(b.charger_id)===String(id));if(b)selectBay(b.id);}
else if(a==='show-map'){view.querySelector('.parking-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}
else if(a==='select-bay'){selectBay(id);if(matchMedia('(max-width: 1500px)').matches)$('#charger-details').scrollIntoView({behavior:'smooth',block:'nearest'});}
else if(a==='parking-floor'){state.parkingFloor=id;const b=state.data.bays.find(b=>(b.floor||'UG1')===id);if(b)selectBay(b.id);}
else if(a.startsWith('map-zoom-')){state.parkingZoom=a==='map-zoom-reset'?1:Math.min(1.75,Math.max(1,state.parkingZoom+(a==='map-zoom-in'?.25:-.25)));updateParkingLive();}
else if(a==='parking-view'){state.parkingView=target.dataset.view;renderPage();}
else if(a==='choose-slot'){state.draft.start=target.dataset.start;state.draft.end=target.dataset.end;state.draft.request_id=requestID();renderPage();$('#booking-start').focus();}
else if(a==='review-booking')bookingReview();
else if(a==='reservation-tab'){state.reservationTab=target.dataset.tab;renderPage();}
else if(a==='reservation-detail')reservationDialog(id);
else if(a==='reservation-edit'){const r=state.data.reservations.find(r=>String(r.id)===id);state.draft={start:localInput(r.start),end:localInput(r.end),charger_id:r.charger_id,vehicle_id:r.vehicle_id,bay_id:r.bay_id,editing:r.id,request_id:requestID()};state.selectedCharger=r.charger_id;state.selectedBay=r.bay_id;state.parkingFloor=r.floor||'UG1';closeDialog();location.hash='parking';changeRoute('parking');$('#booking-start').focus();}
else if(a==='discard-edit'){state.draft=defaultDraft();renderPage();}
else if(a==='reservation-cancel'){const r=state.data.reservations.find(r=>String(r.id)===id);confirmDialog('Cancel this reservation?',`<strong>${esc(intervalLabel(r.start,r.end))}</strong><br>${esc(r.charger_name)} · ${esc(r.bay)} · ${esc(floorName(r.floor))} · ${esc(r.vehicle_name)}<p>The slot will be released. The cancelled record stays in your household history.</p>`,`/api/reservations/${id}/cancel/`,{},'Reservation cancelled. The slot is released.');}
else if(a==='booking-add-vehicle'){state.bookingReturn=true;location.hash='household';changeRoute('household');vehicleDialog();}
else if(a==='return-booking'){state.bookingReturn=false;location.hash='parking';changeRoute('parking');}
else if(a==='vehicle-add')vehicleDialog();
else if(a==='vehicle-edit')vehicleDialog(id);
else if(a==='vehicle-archive'){const v=state.data.vehicles.find(v=>String(v.id)===id);confirmDialog('Archive this vehicle?',`${esc(v.name)} · ${esc(v.plate)}<p>Historical records are preserved. Future reservations must be cancelled or reassigned before archiving.</p>`,`/api/vehicles/${id}/archive/`,{},'Vehicle archived. Historical records are unchanged.');}
else if(a==='household-edit')openDialog('Edit household',`<form id="dialog-form"><label class="field">Household name<input name="name" required maxlength="120" value="${esc(state.data.household.name)}"></label>${errorMarkup()}<div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">Cancel</button><button class="button" type="submit">Save household</button></div></form>`,{submit:form=>mutate('/api/household/',Object.fromEntries(new FormData(form)),{success:'Household name updated.'})});
else if(a==='invite')inviteDialog();
else if(a==='copy-invitation'){const input=$('#invitation-link');try{await navigator.clipboard.writeText(input.value);$('#copy-status').textContent='Invitation link copied.';}catch{input.focus();input.select();$('#copy-status').textContent='Select and copy the highlighted invitation link.';}}
else if(a==='invite-revoke')confirmDialog('Revoke this invitation?','The existing link will stop working. You can create another invitation later.',`/api/invitations/${id}/revoke/`,{},'Invitation revoked.');
else if(a==='member-remove'){const m=state.data.members.find(m=>String(m.id)===id);confirmDialog('Remove household access?',`${esc(m.name)} will lose access to this household. Historical bookings and charging records will remain.`,`/api/members/${id}/remove/`,{},'Household access removed.');}
else if(a==='history-reset'){state.historyMonth=monthOf(now());state.historyVehicle='';renderPage();}
else if(a==='session-detail')sessionDialog(id);
else if(a==='invoice-detail')invoiceDialog(id);
else if(a==='more')openDialog('More from your household',`<nav class="dialog-nav" aria-label="Household pages"><a href="#history" data-action="nav-dialog">${icon('energy')} Charging history</a><a href="#billing" data-action="nav-dialog">${icon('invoice')} Billing &amp; invoices</a></nav><h3>The VoltoShare project</h3><p class="muted">Explore assumptions and the team presentation. These are project simulations, not your household bills. Links open in a new tab.</p><nav class="dialog-nav" aria-label="Project resources"><a href="${esc($('#project-finance-link').href)}" target="_blank" rel="noopener">${icon('invoice')} Financial scenarios ↗</a><a href="${esc($('#project-presentation-link').href)}" target="_blank" rel="noopener">${icon('building')} Project presentation ↗</a></nav>`);
else if(a==='nav-dialog')closeDialog();
else if(a==='account')openDialog('Your account',`<p><strong>${esc(state.data.user.name)}</strong><br>${esc(state.data.user.email)}</p><p class="muted">${esc(state.data.household.name)} · ${esc(state.data.role)}</p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">Close</button><button class="button" data-action="logout">Sign out</button></div>`);
else if(a==='logout')$('.sidebar-bottom form').requestSubmit();
}catch(error){if(dialog.open)dialogError(error);else toast(error.message);}});
setInterval(()=>{if(state.data&&!document.hidden&&!state.busy)refresh({silent:true,render:false}).catch(()=>{});},20000);
state.route=location.hash.slice(1)||'dashboard';if(!['dashboard','parking','history','household','billing'].includes(state.route))state.route='dashboard';
refresh().catch(()=>{});

// Arrow keys navigate the physical bay grid; Enter/Space selects a bay.
document.addEventListener('keydown',e=>{const b=e.target.closest('.garage-plan [data-action="select-bay"]');if(!b||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const dr=e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0,dc=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;const candidates=[...b.closest('.garage-plan').querySelectorAll('[data-action="select-bay"]')];const next=candidates.find(x=>+x.dataset.row===+b.dataset.row+dr&&+x.dataset.column===+b.dataset.column+dc);if(next){e.preventDefault();next.focus({preventScroll:true});next.scrollIntoView({block:'nearest',inline:'nearest'});}});
